export async function mountScene(root){
 const viewport=root.querySelector('#scene-stage'),loading=root.querySelector('#scene-loading'),progress=root.querySelector('#scene-progress'),play=root.querySelector('#scene-play'),phase=root.querySelector('#scene-phase');
 let p=12,playing=false,lastTime=0,raf=0,active=true,drawFrame=0,cameraName='front';
 function pause(){playing=false;cancelAnimationFrame(raf);play.textContent='播放回合';play.setAttribute('aria-pressed','false');}
 try{
  const [THREE,{GLTFLoader},{OrbitControls},{RoomEnvironment}]=await Promise.all([import('https://esm.sh/three@0.180.0'),import('https://esm.sh/three@0.180.0/examples/jsm/loaders/GLTFLoader.js'),import('https://esm.sh/three@0.180.0/examples/jsm/controls/OrbitControls.js'),import('https://esm.sh/three@0.180.0/examples/jsm/environments/RoomEnvironment.js')]);
  const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
  renderer.domElement.setAttribute('role','img');renderer.domElement.setAttribute('aria-label','两辆 F1 概念车的侧面三维攻防示意，可拖动旋转');viewport.prepend(renderer.domElement);
  const scene=new THREE.Scene();scene.background=new THREE.Color('#17212e');
  const camera=new THREE.OrthographicCamera(-6,6,3,-3,.1,150),orbit=new OrbitControls(camera,renderer.domElement);orbit.enablePan=false;orbit.enableDamping=false;orbit.minPolarAngle=THREE.MathUtils.degToRad(74);orbit.maxPolarAngle=THREE.MathUtils.degToRad(88);orbit.minAzimuthAngle=THREE.MathUtils.degToRad(-70);orbit.maxAzimuthAngle=THREE.MathUtils.degToRad(70);orbit.minZoom=.82;orbit.maxZoom=2.5;orbit.target.set(0,.53,0);
  const pmrem=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment(),env=pmrem.fromScene(room,.025);scene.environment=env.texture;scene.environmentIntensity=.65;room.dispose();pmrem.dispose();
  scene.add(new THREE.HemisphereLight(0xddeaff,0x3b4657,.9));const key=new THREE.DirectionalLight(0xfff3e5,2.3);key.position.set(4,8,6);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-10,right:10,top:7,bottom:-7});key.shadow.bias=-.0005;key.shadow.normalBias=.015;scene.add(key);const fill=new THREE.DirectionalLight(0xadcfff,1.1);fill.position.set(-3,5,-7);scene.add(fill);
  const floorMat=new THREE.MeshStandardMaterial({color:0x303d4d,roughness:.96,metalness:.02}),ground=new THREE.Mesh(new THREE.PlaneGeometry(160,13),floorMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.025;ground.receiveShadow=true;scene.add(ground);
  const lineMat=new THREE.MeshStandardMaterial({color:0x8d99aa,roughness:.9});for(const z of [-5.75,5.75]){const line=new THREE.Mesh(new THREE.PlaneGeometry(160,.09),lineMat);line.rotation.x=-Math.PI/2;line.position.set(0,-.020,z);scene.add(line);}
  const marks=new THREE.Group();scene.add(marks);const kerb=new THREE.MeshStandardMaterial({color:0x7b3542,roughness:.8});for(let i=-18;i<19;i++){const m=new THREE.Mesh(new THREE.BoxGeometry(1.4,.035,.42),i%2?kerb:lineMat);m.position.set(i*1.4,0,-6);marks.add(m);}
  const gltf=await new GLTFLoader().loadAsync(new URL('./assets/f1-two-cars.glb',import.meta.url).href);scene.add(gltf.scene);const a=gltf.scene.getObjectByName('Car_A'),b=gltf.scene.getObjectByName('Car_B');if(!a||!b)throw Error('Missing car nodes');gltf.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});
  const wheels=[];for(const car of [a,b]){const centres=[[1.4,.365,.86],[1.4,.365,-.86],[-1.46,.385,.86],[-1.46,.385,-.86]],groups=centres.map(c=>{const g=new THREE.Group();g.position.set(...c);car.add(g);return g;});scene.updateMatrixWorld(true);const meshes=[];car.traverse(o=>{if(o.isMesh&&/^(Tyre|Wheel_)/.test(o.name))meshes.push(o);});for(const m of meshes){const mid=new THREE.Box3().setFromObject(m).getCenter(new THREE.Vector3());car.worldToLocal(mid);let index=0,d=Infinity;centres.forEach((c,i)=>{const q=mid.distanceToSquared(new THREE.Vector3(...c));if(q<d){d=q;index=i;}});groups[index].attach(m);}groups.forEach((g,i)=>wheels.push({g,r:centres[i][1]}));}
  const labelA=root.querySelector('#car-a-label'),labelB=root.querySelector('#car-b-label'),anchor=new THREE.Vector3();
  function label(el,car){anchor.set(car.position.x,1.5,car.position.z).project(camera);const w=viewport.clientWidth,h=viewport.clientHeight;el.style.left=Math.max(5,Math.min(w-100,(anchor.x*.5+.5)*w-35))+'px';el.style.top=Math.max(7,Math.min(h-30,(-anchor.y*.5+.5)*h))+'px';}
  function draw(){if(!active||!viewport.clientWidth)return;scene.updateMatrixWorld(true);renderer.render(scene,camera);label(labelA,a);label(labelB,b);}
  function schedule(){if(!drawFrame)drawFrame=requestAnimationFrame(()=>{drawFrame=0;draw();});}
  function pose(){const q=p/100,gap=-3+6*q;a.position.set(gap/2,0,1.4);b.position.set(-gap/2,0,-1.4);wheels.forEach(w=>w.g.rotation.z=-q*24/w.r);marks.position.x=-(q*24%2.8);progress.value=String(Math.round(p));phase.textContent=q<.36?'接近':q>.64?'前出':'并排';root.dataset.progress=String(Math.round(p));root.querySelectorAll('[data-progress]').forEach(btn=>{const n=+btn.dataset.progress;const selected=n===12?q<.36:n===50?q>=.36&&q<=.64:q>.64;btn.classList.toggle('active',selected);btn.setAttribute('aria-pressed',String(selected));});schedule();}
  function setCamera(){camera.position.set(...{front:[8,3.3,16],side:[0,2.2,18],rear:[-8,3.3,16]}[cameraName]);camera.zoom=1;orbit.target.set(0,.53,0);orbit.update();root.querySelectorAll('[data-camera]').forEach(btn=>{const selected=btn.dataset.camera===cameraName;btn.classList.toggle('active',selected);btn.setAttribute('aria-pressed',String(selected));});root.dataset.camera=cameraName;schedule();}
  function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;if(!w||!h)return;const aspect=w/h,horizontal=Math.max(10,4.6*aspect),vertical=horizontal/aspect;Object.assign(camera,{left:-horizontal/2,right:horizontal/2,top:vertical/2,bottom:-vertical/2});camera.updateProjectionMatrix();renderer.setSize(w,h,false);active=true;schedule();}
  function tick(now){if(!playing)return;if(lastTime)p=Math.min(100,p+Math.min(now-lastTime,100)/85*Number(root.querySelector('#scene-speed').value));lastTime=now;pose();if(p>=100)pause();else raf=requestAnimationFrame(tick);}
  root.querySelectorAll('[data-camera]').forEach(btn=>btn.addEventListener('click',()=>{cameraName=btn.dataset.camera;setCamera();}));root.querySelectorAll('[data-progress]').forEach(btn=>btn.addEventListener('click',()=>{pause();p=+btn.dataset.progress;pose();}));progress.addEventListener('input',()=>{pause();p=+progress.value;pose();});play.addEventListener('click',()=>{if(playing){pause();return;}if(p>=100)p=0;playing=true;lastTime=0;play.textContent='暂停';play.setAttribute('aria-pressed','true');raf=requestAnimationFrame(tick);});orbit.addEventListener('change',schedule);
  const ro=new ResizeObserver(resize);ro.observe(viewport);const observer=new IntersectionObserver(entries=>{active=entries[0].isIntersecting;if(!active)pause();else schedule();});observer.observe(root);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
  root.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);loading.hidden=true;labelA.hidden=false;labelB.hidden=false;root.dataset.ready='true';resize();setCamera();pose();return{pause,resize};
 }catch(error){loading.querySelector('span').innerHTML='三维模型暂未载入，请检查网络后重试。<br><button class="button section-space" id="retry-scene">重新载入</button>';loading.setAttribute('role','alert');root.dataset.error=String(error?.message||error);root.querySelector('#retry-scene').addEventListener('click',()=>location.reload());return{pause,resize:()=>{}};}
}
